'use strict';
let planA=structuredClone(current), scenarioAction=false;
const text=(id,value)=>$(id).textContent=value;
const copyInput=r=>({...r.input});
function applyPlan(input){const result=SU.calculate(input);for(const key of ['loan','debt','start','end','rate','interval','net','expenses'])form.elements[key].value=input[key]??'';$('loan-range').value=input.loan;scenarioAction=true;render(result);scenarioAction=false;return result;}
function comparison(r){const a=planA;const fields=[['Lån hver måned',kr(Number(a.input.loan)*100),kr(Number(r.input.loan)*100)],['Gæld ved start',kr(Number(a.input.debt)*100),kr(Number(r.input.debt)*100)],['Periode',`${date(a.start)} – ${date(a.end)}`,`${date(r.start)} – ${date(r.end)}`],['Rente efter studiet',String(a.rate).replace('.',',')+' %',String(r.rate).replace('.',',')+' %'],['Gæld ved studieslut',exact(a.study.debt),exact(r.study.debt)],['Nye renter i hele forløbet',exact(a.study.interest+a.payment.interest),exact(r.study.interest+r.payment.interest)],['Afsæt pr. måned inkl. gebyr',exact(a.payment.maxPayment/a.interval),exact(r.payment.maxPayment/r.interval)],['Første betaling',date(a.payment.start),date(r.payment.start)],['Forventet gældfri',date(a.payment.end),date(r.payment.end)],['Tilbage efter SU-reserve',a.budget?exact(a.budget.left):'Tilføj budget',r.budget?exact(r.budget.left):'Tilføj budget']];$('plan-rows').replaceChildren(...fields.map(([label,av,bv])=>{const row=document.createElement('tr');for(const [i,value]of [label,av,bv].entries()){const cell=document.createElement(i===0?'th':'td');cell.textContent=value;if(i===0)cell.scope='row';row.append(cell);}return row;}));const diff=r.study.debt-a.study.debt;const monthly=Number(r.input.loan)-Number(a.input.loan);text('plan-insight',diff===0?'Planerne har samme gæld ved studieslut. Se også forskellen i renter og betaling efter studiet.':`Plan B giver ${kr(Math.abs(diff))} ${diff<0?'mindre':'mere'} gæld ved studieslut.${monthly?` Du har samtidig ${kr(Math.abs(monthly)*100)} ${monthly<0?'mindre':'mere'} udbetalt hver lånemåned.`:''}`);}
function math(r){const first=r.study.rows[0],startDebt=Number(r.input.debt)*100,loan=Number(r.input.loan)*100;let html=`<h3>Gælden ved studieslut</h3><p>${exact(startDebt)} i startgæld + ${exact(r.study.borrowed)} i nye lån + ${exact(r.study.interest)} i renter = <strong>${exact(r.study.debt)}</strong>.</p><h3>Den første måneds rente</h3><p>(${exact(startDebt)} + ${exact(loan)}) × 4 % / 12 = <strong>${exact(first.interest)}</strong>, afrundet til øre. Næste måned beregnes der også rente af tidligere renter.</p><h3>Fra studieslut til betalingsstart</h3><p>${exact(r.study.debt)} + ${exact(r.payment.waitInterest)} i renter i ventetiden = <strong>${exact(r.payment.opening)}</strong> ved starten af betalingsåret.</p>`;if(r.payment.start)html+=`<h3>Din månedlige reserve</h3><p>Største opkrævning inklusive gebyr: ${exact(r.payment.maxPayment)} / ${r.interval} måned${r.interval===2?'er':''} = <strong>${exact(r.payment.maxPayment/r.interval)} pr. måned</strong>. Sidste betaling kan være mindre.</p><p>Scenariet vælger op til ${r.payment.years} års tilbagebetaling ud fra gælden ved betalingsstart og beregner en fast ydelse med ${r.rate} % rente. Gebyret er 15 kr. pr. opkrævning.</p>`;if(r.budget)html+=`<h3>Dit budget</h3><p>${exact(r.budget.net)} efter skat − ${exact(r.budget.expenses)} i udgifter − ${exact(r.budget.reserve)} i SU-reserve = <strong>${exact(r.budget.left)}</strong> tilbage.</p>`;$('math-content').innerHTML=html;}
function mlFeatures(loan,months,initial){return [loan,months,initial,loan*months,initial*months,loan*months*months];}
function lab(r){const m=window.SU_MODEL;if(!m){text('lab-prediction','Modelresultatet kunne ikke indlæses. Beregneren fungerer stadig.');return;}const loan=Number(r.input.loan),initial=Number(r.input.debt),months=r.study.rows.length;if(initial>m.ranges.initial[1]||months>m.ranges.months[1]){text('lab-prediction','Dit scenarie ligger uden for modellens træningsområde (højst 84 måneder og 100.000 kr. i startgæld). Brug den præcise beregner ovenfor.');return;}const f=mlFeatures(loan,months,initial);const predicted=Math.max(0,m.coefficients[0]+f.reduce((sum,v,i)=>sum+(v-m.means[i])/m.scales[i]*m.coefficients[i+1],0));$('lab-prediction').innerHTML=`<h3>Modellen prøver dine viste tal</h3><div class="prediction-grid"><p>ML-estimat<strong>${exact(predicted*100)}</strong></p><p>Beregnerens facit<strong>${exact(r.study.debt)}</strong></p><p>Forskel<strong>${exact(Math.abs(predicted*100-r.study.debt))}</strong></p></div><p>Det er beregnerens facit, der bruges i dit overblik. ML-estimatet påvirker ikke din plan.</p>`;}
function refreshFeatures(r){comparison(r);math(r);lab(r);if(!scenarioAction)text('scenario-message','');}
document.addEventListener('su:calculated',e=>refreshFeatures(e.detail));
document.querySelectorAll('[data-chapter]').forEach(button=>button.addEventListener('click',()=>{guideIndex=Number(button.dataset.chapter);explain();}));
document.querySelectorAll('[data-scenario]').forEach(button=>button.addEventListener('click',()=>{const input=copyInput(planA);let message='';switch(button.dataset.scenario){case 'less':input.loan=Math.max(0,Number(input.loan)-500);message='Plan B: lavere lån. Du får også færre penge udbetalt under studiet.';break;case 'year':input.end=String(Number(input.end.slice(0,4))+1)+input.end.slice(4);message='Plan B: ét ekstra år, hvor du fortsætter med at låne hver måned. Det forudsætter, at du har ret til lån hele perioden.';break;case 'rate':input.rate=Number((Number(input.rate)+2).toFixed(2));message='Plan B: renten er 2 procentpoint højere fra studieslut. Der beregnes en ny startydelse; en renteændring i en eksisterende officiel plan kan i stedet ændre løbetiden.';break;}try{applyPlan(input);text('scenario-message',message);}catch(e){text('scenario-message',e.message);}}));
$('reset-plan').addEventListener('click',()=>{applyPlan(copyInput(planA));text('scenario-message','Plan A er gendannet.');});
$('save-plan').addEventListener('click',()=>{planA=structuredClone(current);comparison(current);text('scenario-message','De senest beregnede tal er nu dit udgangspunkt i plan A.');});
const quiz=SU.calculate({loan:2000,debt:0,start:'2026-01',end:'2028-12',rate:2.85,interval:2});
document.querySelectorAll('[data-guess]').forEach(button=>button.addEventListener('click',()=>{const correct=button.dataset.guess==='76600';document.querySelectorAll('[data-guess]').forEach(b=>{b.disabled=true;b.classList.toggle('quiz-correct',b.dataset.guess==='76600');});text('quiz-answer',`${correct?'Ja, det er det nærmeste svar!':'Et godt sted at undersøge renterne:'} Du låner 72.000 kr. i alt, og beregningen lægger ${exact(quiz.study.interest)} i renter oveni. Gælden bliver ${exact(quiz.study.debt)}. Renterne vokser også på de renter, der allerede er tilskrevet.`);$('quiz-reset').hidden=false;}));
$('quiz-reset').addEventListener('click',()=>{document.querySelectorAll('[data-guess]').forEach(b=>{b.disabled=false;b.classList.remove('quiz-correct');});text('quiz-answer','');$('quiz-reset').hidden=true;});
if(window.SU_MODEL){const m=window.SU_MODEL;$('lab-stats').innerHTML=`<article><strong>${m.samples.toLocaleString('da-DK')}</strong><span>simulerede scenarier</span></article><article><strong>${m.train_count.toLocaleString('da-DK')} / ${m.test_count.toLocaleString('da-DK')}</strong><span>træning / test</span></article><article><strong>${kr(m.metrics.mae*100)}</strong><span>gennemsnitlig fejl på test</span></article>`;$('lab-method').innerHTML=`<h3>Et eksperiment, der kan gentages</h3><p>Lineær regression med input for lånebeløb, antal måneder, startgæld og tre kombinationer af dem. Der trænes med mindste kvadraters metode. Seed: ${m.seed}. Fordeling: 80 % træning og 20 % urørt test. Skalering beregnes kun på træningsdata.</p><p>Input trækkes uafhængigt og jævnt: 0–3.799 kr./måned, 1–84 måneder og 0–100.000 kr. i startgæld. Facit kommer fra en månedlig beregning med 4 % rente. Det er scenarier, ikke en beskrivelse af danske studerende.</p><div class="table-scroll"><table><caption>Resultater på de 1.000 testscenarier</caption><thead><tr><th>Metode</th><th>Gennemsnitlig absolut fejl</th></tr></thead><tbody><tr><td>Altid træningssættets gennemsnit</td><td>${exact(m.metrics.baseline_mae*100)}</td></tr><tr><td>Trænet regression</td><td>${exact(m.metrics.mae*100)}</td></tr><tr><td>Den præcise beregner (facit)</td><td>0,00 kr.</td></tr></tbody></table></div><p>RMSE: ${exact(m.metrics.rmse*100)}. Største testfejl: ${exact(m.metrics.max_error*100)}.</p><h3>Hvad viser det?</h3><p>Modellen kan efterligne beregneren inden for det simulerede område. Den tilføjer ikke præcision, og den forudsiger hverken ledighed, overraskelse eller betalingsproblemer. Testfejlene er ikke en garanti for fejl på nye input. Derfor bruger produktet fortsat beregningsreglerne.</p>`;}
refreshFeatures(current);
